var response = await client.Products.CreateProductAsync(new Dictionary<string, object?>
{
    ["name"] = "Blue Mug", ["sku"] = "MUG-BLUE", ["base_price"] = 12.5, ["transaction_no"] = "IMPORT-2026-10-18",
}, transactionNo: "IMPORT-2026-10-18");
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
