import_product_reviews.code:
var response = await client.Products.ImportProductReviewsAsync(101, new Dictionary<string, object?>
{
    ["product"] = new Dictionary<string, object?>
    {
        ["reviews"] = new object[]
        {
            new Dictionary<string, object?>
            {
                ["name"] = "Sam Lee", ["email"] = "sam@example.com", ["rating"] = 5,
                ["review"] = "Great shirt", ["status"] = "approved",
            },
        },
    },
}, transactionNo: "IMPORT-2026-10-18");
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var product = (IReadOnlyDictionary<string, object?>)body["product"]!;
foreach (var review in ((IReadOnlyList<object?>)product["reviews"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{review["id"]} {review["name"]} {review["rating"]} {review["status"]}");

